import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';

@Component({
  selector: 'app-admin-login',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './admin-login.component.html'
})
export class AdminLoginComponent {
  username: string = '';
  password: string = '';
  showPassword: boolean = false;
  errorMessage: string = '';
  loading: boolean = false;

  private apiUrl = 'https://amitmaurya.runasp.net/api/admin/login';

  constructor(
    private router: Router,
    private http: HttpClient
  ) {}

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
  }

  async handleLogin(): Promise<void> {
    if (!this.username || !this.password) {
      this.errorMessage = 'Please enter both User ID and Password';
      return;
    }

    this.loading = true;
    this.errorMessage = '';

    try {
      const response = await firstValueFrom(
        this.http.post<any>(this.apiUrl, {
          username: this.username,
          password: this.password
        })
      );

      if (response && response.success) {
        sessionStorage.setItem('admin_logged_in', 'true');
        sessionStorage.setItem('admin_username', response.username || this.username);
        if (response.token) {
          sessionStorage.setItem('admin_token', response.token);
        }
        this.router.navigate(['/admin']);
        return;
      } else {
        this.errorMessage = response?.message || 'Invalid User ID or Password.';
      }
    } catch (err: any) {
      if (err.error && err.error.message) {
        this.errorMessage = err.error.message;
      } else if (err.status === 401 || err.status === 400) {
        this.errorMessage = 'Invalid User ID or Password.';
      } else {
        // Fallback for offline mode if DB/Backend API is unreachable
        const storedUser = localStorage.getItem('admin_user_id') || 'admin';
        const storedPass = localStorage.getItem('admin_password') || 'admin123';

        const isValidUser = (this.username === 'admin' || this.username === storedUser);
        const isValidPass = (this.password === 'admin123' || this.password === 'password123' || this.password === storedPass);

        if (isValidUser && isValidPass) {
          sessionStorage.setItem('admin_logged_in', 'true');
          sessionStorage.setItem('admin_username', this.username);
          this.router.navigate(['/admin']);
          return;
        } else {
          this.errorMessage = 'Invalid User ID or Password.';
        }
      }
    } finally {
      this.loading = false;
    }
  }
}
<div style="max-width: 440px; margin: 40px auto; padding: 28px;" class="card">
  <div style="text-align: center; margin-bottom: 24px;">
    <div class="brand-icon" style="width: 48px; height: 48px; margin: 0 auto 12px; font-size: 1.4rem;">A</div>
    <h2 class="page-title" style="font-size: 1.5rem;">Admin Dashboard Sign In</h2>
    <p class="page-subtitle" style="font-size: 0.85rem;">Access Full CRUD Control Panel </p>
  </div>

  <div *ngIf="errorMessage" style="background: rgba(239, 68, 68, 0.15); color: #fca5a5; border: 1px solid rgba(239, 68, 68, 0.3); border-radius: 8px; padding: 10px 14px; font-size: 0.85rem; margin-bottom: 20px;">
    ⚠️ {{ errorMessage }}
  </div>

  <form (ngSubmit)="handleLogin()">
    <div class="form-group">
      <label>User ID *</label>
      <input type="text" class="form-control" name="username" [(ngModel)]="username" required placeholder="Enter User ID">
    </div>

    <div class="form-group">
      <label>Password *</label>
      <div style="position: relative; display: flex; align-items: center;">
        <input 
          [type]="showPassword ? 'text' : 'password'" 
          class="form-control" 
          name="password" 
          [(ngModel)]="password" 
          required 
          placeholder="Enter Password"
          style="padding-right: 44px;">
        <button 
          type="button" 
          (click)="togglePasswordVisibility()" 
          style="position: absolute; right: 10px; background: transparent; border: none; color: #94a3b8; cursor: pointer; font-size: 1.15rem; display: flex; align-items: center; justify-content: center; padding: 4px; transition: color 0.2s;"
          [attr.aria-label]="showPassword ? 'Hide password' : 'Show password'"
          [title]="showPassword ? 'Hide password' : 'Show password'">
          {{ showPassword ? '👁️' : '🙈' }}
        </button>
      </div>
    </div>

    <button type="submit" class="btn btn-primary" style="width: 100%; justify-content: center; margin-top: 10px;" [disabled]="loading">
      {{ loading ? 'Signing In...' : 'Sign In to Admin Panel ➔' }}
    </button>
  </form>
</div>
